1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0">
6	<title>Blackwell Thread Hierarchy</title>
7	<link rel="stylesheet" href="../viz-base.css">
8	<script src="../viz-base.js"></script>
9	<style>
10	  body { padding: 16px 28px; max-width: 980px; margin: 0 auto; }
11	  h1 { font-size: 28px; line-height: 1.1; margin-bottom: 6px; }
12	  .hier { max-width: 860px; margin: 0 auto; }
13	
14	  .lvl { border: 2.5px solid; border-radius: 12px; position: relative;
15	         padding: 26px 14px 14px; margin: 0; cursor: pointer; transition: box-shadow .15s; }
16	  .lvl + .lvl, .lvl .lvl { margin-top: 0; }
17	  .lvl.sel { box-shadow: 0 0 0 3px rgba(0,0,0,.16); }
18	  .tag { position: absolute; top: -11px; left: 14px; color: #fff; font-size: 11px;
19	         font-weight: 700; padding: 2px 10px; border-radius: 4px; letter-spacing: .02em; }
20	
21	  /* one color per level (viz-base group palette) */
22	  .lvl-grid    { border-color:#9d6eb5; background:#f6f1fa; }      .lvl-grid    > .tag{ background:#9d6eb5; }
23	  .lvl-cluster { border-color:#5b9bd5; background:#eef5fc; }      .lvl-cluster > .tag{ background:#5b9bd5; }
24	  .lvl-cta     { border-color:#45b5a5; background:#ecfaf7; }      .lvl-cta     > .tag{ background:#2f8f82; }
25	  .lvl-wg      { border-color:#ed9a3c; background:#fef4e7; }      .lvl-wg      > .tag{ background:#d97e1f; }
26	  .lvl-warp    { border-color:#5fb85f; background:#eefaee; }      .lvl-warp    > .tag{ background:#4a9a4a; }
27	
28	  .ctarow { display:grid; grid-template-columns: 1fr auto; gap:12px; align-items:stretch; }
29	  .warprow { display:grid; grid-template-columns: 1fr auto auto auto; gap:8px; align-items:stretch; }
30	  .ghost { border:2px dashed #b6bdc6; border-radius:10px; background:#f4f6f8; color:#8a93a0;
31	           font-size:11px; font-weight:700; display:flex; align-items:center; justify-content:center;
32	           min-width:46px; padding:8px; text-align:center; }
33	
34	  .threads { display:grid; grid-template-columns: repeat(16, 1fr); gap:3px; margin-top:4px; cursor:pointer; }
35	  .th { height:14px; border-radius:3px; background:#d95555; opacity:.85; }
36	  .threads.sel .th { box-shadow: inset 0 0 0 1px #7a2222; }
37	
38	  .detail-panel { max-width:860px; margin:14px auto 0; border:1px solid var(--border);
39	    border-radius:10px; background:var(--surface); padding:10px 16px; min-height:88px; }
40	  .dp-title { font-size:12.5px; font-weight:700; margin-bottom:4px; }
41	  .dp-body  { font-size:12px; line-height:1.6; color:#475569; }
42	  .dp-body code { font-family:'SF Mono','Fira Code',monospace; font-size:11px; background:#f1f5f9;
43	    padding:1px 5px; border-radius:3px; color:#1e293b; }
44	</style>
45	</head>
46	<body>
47	<h1>Blackwell Thread Hierarchy</h1>
48	<div class="sub">click a level — thread → warp → warpgroup → CTA → cluster → grid</div>
49	
50	<div class="hier" id="hier">
51	  <div class="lvl lvl-grid" data-k="grid">
52	    <span class="tag">GRID — one kernel launch</span>
53	    <div class="lvl lvl-cluster" data-k="cluster">
54	      <span class="tag">CLUSTER — CTAs across SMs (DSMEM)</span>
55	      <div class="ctarow">
56	        <div class="lvl lvl-cta" data-k="cta">
57	          <span class="tag">CTA — thread block · one SM</span>
58	          <div class="lvl lvl-wg" data-k="wg">
59	            <span class="tag">WARPGROUP — 4 warps · 128 threads</span>
60	            <div class="warprow">
61	              <div class="lvl lvl-warp" data-k="warp">
62	                <span class="tag">WARP — 32 threads (SIMT)</span>
63	                <div class="threads" id="threads" data-k="thread"></div>
64	              </div>
65	              <div class="ghost">warp 1</div>
66	              <div class="ghost">warp 2</div>
67	              <div class="ghost">warp 3</div>
68	            </div>
69	          </div>
70	        </div>
71	        <div class="ghost">CTA 1<br>…</div>
72	      </div>
73	    </div>
74	  </div>
75	</div>
76	
77	<div class="detail-panel" id="detail">
78	  <div class="dp-title" id="dpt"></div>
79	  <div class="dp-body" id="dpb"></div>
80	</div>
81	
82	<script>
83	(function () {
84	  var INFO = {
85	    thread:  ["Thread", "The scalar unit of execution, identified by its <b>lane ID</b> within the warp. Each lane keeps its own registers and data."],
86	    warp:    ["Warp — 32 threads", "32 threads execute in lockstep (<b>SIMT</b>): the lanes issue the same instruction together, each with its own registers."],
87	    wg:      ["Warpgroup — 4 warps, 128 threads", "Introduced on Hopper as the unit for warpgroup-level MMA (<code>wgmma</code>); on Blackwell it is also the cooperation unit for <b>Tensor Memory</b> access (128 threads move a TMEM tile together)."],
88	    cta:     ["CTA — Cooperative Thread Array", "A CUDA thread block. Runs on a single <b>SM</b> and owns that SM's shared memory. One or more warpgroups."],
89	    cluster: ["Cluster — cooperating CTAs", "A group of CTAs (on different SMs) that can synchronize and read each other's shared memory (<b>DSMEM</b>). Blackwell adds dynamic scheduling (CLC) and 2-CTA cooperative MMA."],
90	    grid:    ["Grid — one kernel launch", "All threads of a kernel launch, organized into clusters (or directly CTAs). Tiles of the problem are mapped onto CTAs/clusters."]
91	  };
92	  var hier = document.getElementById('hier');
93	  var threads = document.getElementById('threads');
94	  for (var i = 0; i < 32; i++) { var t = document.createElement('div'); t.className = 'th'; threads.appendChild(t); }
95	  var dpt = document.getElementById('dpt'), dpb = document.getElementById('dpb');
96	
97	  function select(k) {
98	    hier.querySelectorAll('.sel').forEach(function (e) { e.classList.remove('sel'); });
99	    var el = hier.querySelector('[data-k="' + k + '"]');
100	    if (el) el.classList.add('sel');
101	    dpt.innerHTML = INFO[k][0];
102	    dpb.innerHTML = INFO[k][1];
103	  }
104	  hier.addEventListener('click', function (e) {
105	    var el = e.target.closest('[data-k]');
106	    if (el) select(el.dataset.k);
107	  });
108	  select('wg');   // default: the warpgroup (the key Hopper/Blackwell unit)
109	})();
110	</script>
111	</body>
112	</html>
