9	<style>
10	  html { overflow-x: hidden; }
11	  body { padding: 14px 18px; max-width: 1300px; width: 100%; box-sizing: border-box; margin: 0 auto; overflow-x: hidden; }
12	  h1 { font-size: 28px; line-height: 1.1; margin-bottom: 12px; }
13	
14	  .diagram-wrap {
15	    max-width: min(1000px, 100%); margin: 0 auto; position: relative;
16	  }
17	  .gpu-row {
18	    display: grid; grid-template-columns: 1fr auto; gap: 14px;
19	    align-items: stretch; margin-bottom: 12px;
20	  }
21	  .sm-ghost {
22	    border: 3px dashed #94a3b8; border-radius: 14px;
23	    background: #f1f5f9; min-width: 80px;
24	    display: flex; align-items: center; justify-content: center;
25	    color: #94a3b8; font-size: 14px; font-weight: 700;
26	    position: relative;
27	  }
28	  .sm-ghost-label {
29	    position: absolute; top: -12px; left: 14px;
30	    background: #94a3b8; color: #fff; font-size: 13px; line-height: 1.1; font-weight: 700;
31	    padding: 2px 10px; border-radius: 4px; letter-spacing: .04em;
32	  }
33	
34	  /* ── SM outer box ──────────────────────────────────────── */
35	  .sm-box {
36	    border: 3px solid #334155; border-radius: 14px;
37	    background: #f8fafc; padding: 16px 20px 22px;
38	    position: relative; margin-bottom: 12px;
39	  }
40	  .sm-label {
41	    position: absolute; top: -12px; left: 24px;
42	    background: #334155; color: #fff; font-size: 13px; line-height: 1.1; font-weight: 700;
43	    padding: 2px 12px; border-radius: 4px; letter-spacing: .04em;
44	  }
45	
46	  /* ── HW units ──────────────────────────────────────────── */
47	  .hw-unit {
48	    border: 2px solid; border-radius: 8px; padding: 8px 12px;
49	    text-align: center; background: #fff; cursor: pointer;
50	    transition: all .2s;
51	  }
52	  .hw-unit.selected { box-shadow: 0 0 0 3px rgba(0,0,0,.12); }
53	  .hw-name { font-size: 16px; line-height: 1.05; font-weight: 700; margin-bottom: 1px; }
54	  .hw-sub  { font-size: 12.5px; line-height: 1.1; color: #64748b; }
55	
56	  .u-tc   { border-color: #059669; background: #dcfce7; }
57	  .u-tc .hw-name { color: #065f46; }
58	  .u-smem { border-color: #8b5cf6; background: #ede9fe; }
59	  .u-smem .hw-name { color: #5b21b6; }
60	  .u-tmem { border-color: #f59e0b; background: #fffbeb; }
61	  .u-tmem .hw-name { color: #c2410c; }
62	  .u-rf   { border-color: #dc2626; background: #fee2e2; }
63	  .u-rf .hw-name { color: #991b1b; }
64	  .u-tma  { border-color: #3b82f6; background: #dbeafe; }
65	  .u-tma .hw-name { color: #1e40af; }
66	  .u-cuda { border-color: #6b7280; background: #f3f4f6; }
67	  .u-cuda .hw-name { color: #374151; }
68	
69	  /* ── Layout rows ───────────────────────────────────────── */
70	  .row-compute {
71	    display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 12px;
72	    margin-bottom: 34px;
73	  }
74	  .row-mem {
75	    display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 12px;
76	    margin-bottom: 34px;
77	  }
78	  .row-tma {
79	    display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 12px;
80	    margin-bottom: 0;
81	  }
82	
83	  /* ── HBM outside SM ────────────────────────────────────── */
84	  .hbm-box {
85	    border: 2.5px solid #6b7280; border-radius: 10px;
86	    background: #f3f4f6; color: #374151; padding: 10px 18px;
87	    text-align: center;
88	  }
89	  .hbm-name { font-size: 16px; line-height: 1.1; font-weight: 700; }
90	  .hbm-sub  { font-size: 12.5px; line-height: 1.1; color: #6b7280; }
91	
92	  /* ── SVG overlay ───────────────────────────────────────── */
93	  .svg-overlay {
94	    position: absolute; top: 0; left: 0;
95	    pointer-events: none; z-index: 10;
96	  }
97	  .arrow-label {
98	    font-family: 'SF Mono','Fira Code',monospace;
99	    font-size: 12px; font-weight: 600;
100	  }
101	
102	  /* ── Detail panel ──────────────────────────────────────── */
103	  .detail-panel {
104	    max-width: min(1000px, 100%); margin: 10px auto 0;
105	    border: 1px solid var(--border); border-radius: 10px;
106	    background: var(--surface); padding: 10px 16px;
107	    min-height: 110px; transition: border-color .3s;
108	  }
109	  .detail-panel .dp-title { font-size: 14.5px; font-weight: 700; margin-bottom: 3px; }
110	  .detail-panel .dp-body {
111	    font-size: 14px; line-height: 1.32; color: #475569;
112	  }
113	  .detail-panel .dp-body code {
114	    font-family: 'SF Mono','Fira Code',monospace; font-size: 12px;
115	    background: #f1f5f9; padding: 1px 5px; border-radius: 3px; color: #1e293b;
116	  }
117	  .detail-panel.empty .dp-body { color: #94a3b8; font-size: 16px; line-height: 1.3; }
118	
119	  /* ── Legend ─────────────────────────────────────────────── */
120	  .leg { display: flex; gap: 16px; justify-content: center;
121	    margin: 10px auto 0; max-width: 900px; flex-wrap: wrap; }
122	  .li { display: flex; align-items: center; gap: 5px; font-size: 11px; color: var(--dim); }
123	</style>
124	</head>
125	<body>
126	  <h1>Blackwell SM Architecture</h1>
127	
128	  <div class="diagram-wrap" id="diagramWrap">
129	    <div class="gpu-row">
130	    <div class="sm-box" id="smBox" style="margin-bottom:0;">
131	      <div class="sm-label">Streaming Multiprocessor (SM)</div>
132	
133	      <!-- Compute row: TC (col1), empty (col2), CUDA Core (col3) -->
134	      <div class="row-compute">
135	        <div class="hw-unit u-tc" data-unit="tc" id="boxTC">
136	          <div class="hw-name">Tensor Core (tcgen05)</div>
137	          <div class="hw-sub">5th-gen MMA</div>
138	        </div>
139	        <div></div>
140	        <div class="hw-unit u-cuda" data-unit="cuda" id="boxCUDA">
141	          <div class="hw-name">CUDA Core</div>
142	          <div class="hw-sub">FP/INT units</div>
143	        </div>
144	      </div>
145	
146	      <!-- Memory row: SMEM, TMEM, RegFile -->
147	      <div class="row-mem">
148	        <div class="hw-unit u-smem" data-unit="smem" id="boxSMEM">
149	          <div class="hw-name">Shared Memory (SMEM)</div>
150	          <div class="hw-sub">228 KB per SM</div>
151	        </div>
152	        <div class="hw-unit u-tmem" data-unit="tmem" id="boxTMEM">
153	          <div class="hw-name">Tensor Memory (TMEM)</div>
154	          <div class="hw-sub">TMEM — 128 lanes</div>
155	        </div>
156	        <div class="hw-unit u-rf" data-unit="rf" id="boxRF">
157	          <div class="hw-name">Register File</div>
158	          <div class="hw-sub"></div>
159	        </div>
160	      </div>
161	
162	      <!-- TMA row: col1 only (aligned with SMEM) -->
163	      <div class="row-tma">
164	        <div class="hw-unit u-tma" data-unit="tma" id="boxTMA">
165	          <div class="hw-name">TMA Engine</div>
166	          <div class="hw-sub">Data Mover</div>
167	        </div>
168	        <div></div>
169	        <div></div>
170	      </div>
171	    </div>
172	    <div class="sm-ghost">
173	      <div class="sm-ghost-label">SM ...</div>
174	      &times; N
175	    </div>
176	    </div>
177	
178	    <!-- HBM outside SM -->
179	    <div class="hbm-box" id="boxHBM">
180	      <div class="hbm-name">Global Memory (GMEM)</div>
181	    </div>
182	
183	    <!-- SVG overlay for data path arrows -->
184	    <svg class="svg-overlay" id="arrowSvg" style="display:none;">
185	      <defs>
186	        <marker id="ah-blue" markerWidth="7" markerHeight="5" refX="7" refY="2.5" orient="auto">
187	          <polygon points="0 0,7 2.5,0 5" fill="#3b82f6"/>
188	        </marker>
189	        <marker id="ah-green" markerWidth="7" markerHeight="5" refX="7" refY="2.5" orient="auto">
190	          <polygon points="0 0,7 2.5,0 5" fill="#059669"/>
191	        </marker>
192	        <marker id="ah-amber" markerWidth="7" markerHeight="5" refX="7" refY="2.5" orient="auto">
193	          <polygon points="0 0,7 2.5,0 5" fill="#f59e0b"/>
194	        </marker>
195	      </defs>
196	      <!-- HBM → TMA -->
197	      <path id="arr1" stroke="#3b82f6" stroke-width="2" fill="none" marker-end="url(#ah-blue)"/>
198	      <text id="lbl1" class="arrow-label" fill="#3b82f6"></text>
199	      <!-- TMA → SMEM -->
200	      <path id="arr2" stroke="#3b82f6" stroke-width="2" fill="none" marker-end="url(#ah-blue)"/>
201	      <text id="lbl2" class="arrow-label" fill="#3b82f6"></text>
202	      <!-- SMEM → TC -->
203	      <path id="arr3" stroke="#059669" stroke-width="2" fill="none" marker-end="url(#ah-green)"/>
204	      <text id="lbl3" class="arrow-label" fill="#059669"></text>
205	      <!-- TC → TMEM -->
206	      <path id="arr4" stroke="#f59e0b" stroke-width="2" fill="none" marker-end="url(#ah-amber)"/>
207	      <text id="lbl4" class="arrow-label" fill="#f59e0b"></text>
208	      <!-- TMEM → RF -->
209	      <path id="arr5" stroke="#dc2626" stroke-width="2" fill="none" marker-end="url(#ah-red)"/>
210	      <text id="lbl5" class="arrow-label" fill="#dc2626"></text>
211	      <defs>
212	        <marker id="ah-red" markerWidth="7" markerHeight="5" refX="7" refY="2.5" orient="auto">
213	          <polygon points="0 0,7 2.5,0 5" fill="#dc2626"/>
214	        </marker>
215	      </defs>
216	      <!-- Store path (dashed): RF → SMEM — hidden by default -->
217	      <path id="arr6" stroke="#dc2626" stroke-width="2" fill="none" marker-end="url(#ah-red)" style="display:none;"/>
218	      <text id="lbl6" class="arrow-label" fill="#dc2626" style="display:none;"></text>
219	      <!-- Store path (dashed): SMEM → TMA -->
220	      <path id="arr7" stroke="#3b82f6" stroke-width="2" fill="none" marker-end="url(#ah-blue)"/>
221	      <text id="lbl7" class="arrow-label" fill="#3b82f6"></text>
222	      <!-- Store path (dashed): TMA → HBM -->
223	      <path id="arr8" stroke="#3b82f6" stroke-width="2" fill="none" marker-end="url(#ah-blue)"/>
224	      <text id="lbl8" class="arrow-label" fill="#3b82f6"></text>
225	    </svg>
226	  </div>
227	
228	  <!-- Detail panel -->
229	  <div class="detail-panel empty" id="detailPanel">
230	    <div class="dp-title" id="dpTitle"></div>
231	    <div class="dp-body" id="dpBody">Click a hardware unit to see details. Solid arrows = load path, dashed arrows = store path.</div>
232	  </div>
233	
234	
235	<script>
236	(function() {
237	  /* ── Unit info ─────────────────────────────────────────── */
238	  var info = {
239	    tma: {
240	      title: 'TMA Engine — Hardware Data Mover',
241	      color: '#3b82f6',
242	      body: 'Dedicated DMA engine that copies tensor tiles between <strong>HBM</strong> and <strong>Shared Memory</strong>. Only 1 thread dispatches; HW handles address calculation and swizzling.<br><code>cp.async.bulk.tensor</code>'
243	    },
244	    tc: {
245	      title: 'Tensor Core (tcgen05) — 5th-gen MMA',
246	      color: '#059669',
247	      body: 'Reads A, B from <strong>SMEM</strong>, accumulates into <strong>TMEM</strong>. Supports 128×256 tiles in one instruction. Single thread issues MMA; HW distributes across 128 lanes.<br><code>tcgen05.mma</code> &middot; <code>tcgen05.commit</code>'
248	    },
249	    smem: {
250	      title: 'Shared Memory (SMEM) — 228 KB',
251	      color: '#8b5cf6',
252	      body: 'On-chip scratchpad shared by all threads in a CTA. Staging area for <strong>TMA loads</strong> (HBM&rarr;SMEM) and <strong>TMA stores</strong> (SMEM&rarr;HBM). Swizzled layout avoids bank conflicts.'
253	    },
254	    tmem: {
255	      title: 'Tensor Memory (TMEM) — New in Blackwell',
256	      color: '#f59e0b',
257	      body: 'HW-managed memory private to the SM. 128 lanes &times; N columns of fp32. tcgen05 MMA accumulates here &mdash; no register pressure. <code>tcgen05.ld</code> reads data out for writeback.'
258	    },
259	    rf: {
260	      title: 'Register File',
261	      color: '#dc2626',
262	      body: 'Private per-thread. Writeback: TMEM &rarr; Registers via <code>tcgen05.ld</code> (fp32), then cast fp32&rarr;fp16, store to SMEM, TMA writes back to HBM.'
263	    },
264	    cuda: {
265	      title: 'CUDA Core — Scalar FP/INT Units',
266	      color: '#6b7280',
267	      body: 'General-purpose compute units. Handle fp32&rarr;fp16 casts, address arithmetic, loop control, and data reformatting during writeback. Operate on data in <strong>registers</strong>.'
268	    }
269	  };
270	
271	  /* ── Detail panel ──────────────────────────────────────── */
272	  var panel = document.getElementById('detailPanel');
273	  var titleEl = document.getElementById('dpTitle');
274	  var bodyEl  = document.getElementById('dpBody');
275	  var units = document.querySelectorAll('.hw-unit');
276	  var activeUnit = null;
277	
278	  units.forEach(function(el) {
279	    el.addEventListener('click', function() {
280	      var key = el.dataset.unit;
281	      if (key === activeUnit) { activeUnit = null; clearSelection(); return; }
282	      activeUnit = key;
283	      units.forEach(function(u) { u.classList.remove('selected'); });
284	      el.classList.add('selected');
285	      var d = info[key];
286	      panel.classList.remove('empty');
287	      panel.style.borderColor = d.color;
288	      titleEl.textContent = d.title;
289	      titleEl.style.color = d.color;
290	      bodyEl.innerHTML = d.body;
291	    });
292	  });
293	
294	  function clearSelection() {
295	    units.forEach(function(u) { u.classList.remove('selected'); });
296	    panel.classList.add('empty');
297	    panel.style.borderColor = '';
298	    titleEl.textContent = '';
299	    bodyEl.innerHTML = 'Click a hardware unit to see details. Arrows show the GEMM data path.';
300	  }
301	
302	  /* ── Arrow positioning (rectangular paths) ─────────────── */
303	  function positionArrows() {
304	    var svg = document.getElementById('arrowSvg');
305	    var wrap = document.getElementById('diagramWrap');
306	    var wr = wrap.getBoundingClientRect();
307	
308	    svg.style.display = 'block';
309	    svg.setAttribute('width', wr.width);
310	    svg.setAttribute('height', wr.height);
311	
312	    function rel(el) {
313	      var r = el.getBoundingClientRect();
314	      return {
315	        top: r.top - wr.top, bottom: r.bottom - wr.top,
316	        left: r.left - wr.left, right: r.right - wr.left,
317	        cx: (r.left + r.right) / 2 - wr.left,
318	        cy: (r.top + r.bottom) / 2 - wr.top
319	      };
320	    }
321	
322	    var hbm  = rel(document.getElementById('boxHBM'));
