370	  /* Draw a straight line as a path */
371	  function setRect(id, x1, y1, x2, y2) {
372	    document.getElementById(id).setAttribute('d',
373	      'M'+x1+','+y1+' L'+x2+','+y2);
374	  }
375	
376	  /* Draw a rectangular elbow: start → horiz/vert → turn → end */
377	  function setElbow(id, x1, y1, x2, y2, x3, y3, x4, y4) {
378	    document.getElementById(id).setAttribute('d',
379	      'M'+x1+','+y1+' L'+x2+','+y2+' L'+x3+','+y3+' L'+x4+','+y4);
380	  }
