382	  function setLabel(id, text, x, y, anchor) {
383	    var el = document.getElementById(id);
384	    el.textContent = text;
385	    el.setAttribute('x', x);
386	    el.setAttribute('y', y);
387	    el.setAttribute('text-anchor', anchor || 'start');
